cypress_script:
describe('Multi-level Dropdown Navigation Menu', () => {
  it('should navigate to PDF download when clicking on PDF', () => {
    cy.visit('https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('#menu').should('be.visible');
    cy.get('li').contains('PDF').click();
    cy.url().should('include', '/download/jqueryui/menu/menu.pdf');
  });
  it('should not allow clicking on Disabled option', () => {
    cy.visit('https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('#menu').should('be.visible');
    cy.get('li').contains('Disabled').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Multi-level Dropdown Navigation Menu', () => {
  test('should navigate to PDF download when clicking on PDF', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/jqueryui/menu');
    await expect(page.locator('#menu')).toBeVisible();
    await page.locator('li').withText('PDF').click();
    await expect(page).toHaveURL(/.*\/download\/jqueryui\/menu\/menu.pdf/);
  });
  test('should not allow clicking on Disabled option', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/jqueryui/menu');
    await expect(page.locator('#menu')).toBeVisible();
    await expect(page.locator('li').withText('Disabled')).toBeVisible();
  });
});
